// #3e5463 פוטר שם המוצר בעמוד הכניסה — по решению владельца футер /login = «TAQO» (не «Tenderflow IL»).
// Кейсы: .qa/tests/auth-login/LF-01..LF-06 (LF-M1 — вручную). План: specs/auth-login.md.
// Гость, без входа; формы не отправляются, данные не создаются. @prod-safe.
import { test, expect, Page } from '@playwright/test';

const FOOTER = 'login-footer';
const footer = (page: Page) => page.getByTestId(FOOTER);

async function openLogin(page: Page) {
  await page.goto('/login');
  await expect(footer(page)).toBeVisible();
}

const hScroll = (page: Page) =>
  page.evaluate(() => document.documentElement.scrollWidth - document.documentElement.clientWidth);

// Устройство: без пометки — три прогона (десктоп 1440, iPhone, Android): тикет проверен на 1440 и 390 (раскладка).
test.describe('/login — футер TAQO (#3e5463)', () => {
  test('LF-01 футер ровно "TAQO", текста "Tenderflow IL" на странице нет #3e5463 @prod-safe', async ({ page }) => {
    await openLogin(page);
    await expect(footer(page)).toHaveText('TAQO');
    const texts = await footer(page).evaluate((el) => ({ inner: (el as HTMLElement).innerText, content: el.textContent }));
    expect(texts.inner.trim(), 'innerText').toBe('TAQO');
    expect(texts.content, 'textContent').toBe('TAQO');
    await expect(page.getByText('Tenderflow IL')).toHaveCount(0);
    await expect(page.getByTestId(FOOTER)).toHaveCount(1);
  });

  test('LF-02 футер под формой, не налезает на "הירשם", по центру, dir=ltr #3e5463 @prod-safe', async ({ page }) => {
    await openLogin(page);
    const main = page.getByRole('main');
    const submit = (await main.getByRole('button', { name: 'כניסה לטרמינל', exact: true }).boundingBox())!;
    const signup = (await main.getByRole('link', { name: 'הירשם', exact: true }).boundingBox())!;
    const f = (await footer(page).boundingBox())!;
    expect(f.y, 'футер ниже кнопки входа').toBeGreaterThanOrEqual(submit.y + submit.height);
    const overlaps = f.x < signup.x + signup.width && signup.x < f.x + f.width && f.y < signup.y + signup.height && signup.y < f.y + f.height;
    expect(overlaps, 'футер не пересекается со ссылкой «הירשם»').toBe(false);
    await expect(footer(page)).toHaveAttribute('dir', 'ltr');
    await expect(footer(page)).toHaveCSS('text-align', 'center');
  });

  test('LF-03 нет горизонтальной прокрутки на /login #3e5463 @prod-safe', async ({ page }) => {
    await openLogin(page);
    expect(await hScroll(page), 'горизонтальная прокрутка страницы').toBeLessThanOrEqual(0);
  });

  test('LF-04 RTL страницы не сломан: html dir=rtl, "שכחת סיסמה?" и "הירשם" на месте #3e5463 @prod-safe', async ({ page }) => {
    await openLogin(page);
    await expect(page.locator('html')).toHaveAttribute('dir', 'rtl');
    await expect(page.getByText('שכחת סיסמה?', { exact: true })).toBeVisible();
    await expect(page.getByRole('main').getByRole('link', { name: 'הירשם', exact: true })).toBeVisible();
  });

  test('LF-06 "הירשם" ведёт на /signup, консоль /login без ошибок #3e5463 #5cdc5b @prod-safe', async ({ page }) => {
    const errors: string[] = [];
    page.on('pageerror', (e) => errors.push(`pageerror: ${e.message}`));
    page.on('console', (m) => { if (m.type() === 'error') errors.push(`console: ${m.text()}`); });
    await openLogin(page);
    expect(errors, 'ошибки консоли на /login').toEqual([]);
    await page.getByRole('main').getByRole('link', { name: 'הירשם', exact: true }).click();
    await page.waitForURL('**/signup');
    await expect(footer(page)).toHaveCount(0);
  });
});

// LF-05: футера нет на других страницах и в режиме «забыли пароль» — один десктопный прогон.
test.describe('футер /login отсутствует на других экранах (#3e5463)', () => {
  const pages = [
    { name: '/signup', url: '/signup' },
    { name: '/accept без token', url: '/accept' },
    { name: '/reset-password', url: '/reset-password' },
  ];
  for (const p of pages) {
    test(`LF-05 нет футера на ${p.name} #3e5463 @desktop @prod-safe`, async ({ page }) => {
      await page.goto(p.url);
      await expect(page.locator('main, h1, form').first()).toBeVisible();
      // Если сайт перенаправил на /login — футер там по требованию есть; проверка относится только к самому экрану.
      if (new URL(page.url()).pathname === '/login') {
        test.info().annotations.push({ type: 'note', description: `${p.url} перенаправил на /login — проверка не применима` });
        return;
      }
      await expect(footer(page)).toHaveCount(0);
    });
  }

  test('LF-05 нет футера в режиме "שכחת סיסמה?" #3e5463 @desktop @prod-safe', async ({ page }) => {
    await openLogin(page);
    await page.getByText('שכחת סיסמה?', { exact: true }).click();
    // Режим сброса: кнопка «שלח קישור» и «חזרה לכניסה» (без отправки формы).
    await expect(page.getByRole('button', { name: 'שלח קישור', exact: true })).toBeVisible();
    await expect(footer(page)).toHaveCount(0);
  });
});
